describe('Search Suggestions - Highlight Matching Term', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="search-input"]').as('searchInput');
    cy.get('[data-testid="search-suggestions"]').as('suggestions');
  });

  it('should highlight matching part of search term in suggestions', () => {
    cy.get('@searchInput').type('app');
    cy.get('@suggestions').should('be.visible');

    cy.get('[data-testid="suggestion-item"]').each(($item) => {
      cy.wrap($item).within(() => {
        cy.get('[data-testid="highlight"]').should('exist');
        cy.get('[data-testid="highlight"]').should('have.css', 'background-color');
      });
    });

    cy.get('[data-testid="suggestion-item"]').first().within(() => {
      cy.get('[data-testid="highlight"]').should('contain.text', 'app');
    });
  });

  it('should highlight matching part with case-insensitive search', () => {
    cy.get('@searchInput').type('APP');
    cy.get('@suggestions').should('be.visible');

    cy.get('[data-testid="suggestion-item"]').first().within(() => {
      cy.get('[data-testid="highlight"]').should('exist');
      cy.get('[data-testid="highlight"]').invoke('text').then((text) => {
        expect(text.toLowerCase()).to.equal('app');
      });
    });
  });

  it('should highlight multiple occurrences of matching term', () => {
    cy.get('@searchInput').type('le');
    cy.get('@suggestions').should('be.visible');

    cy.get('[data-testid="suggestion-item"]').first().within(() => {
      cy.get('[data-testid="highlight"]').should('have.length.greaterThan', 0);
      cy.get('[data-testid="highlight"]').each(($highlight) => {
        cy.wrap($highlight).should('contain.text', 'le');
      });
    });
  });

  it('should not show highlight when search input is empty', () => {
    cy.get('@searchInput').clear();
    cy.get('@suggestions').should('not.exist');
  });

  it('should update highlight when search term changes', () => {
    cy.get('@searchInput').type('app');
    cy.get('[data-testid="suggestion-item"]').first().within(() => {
      cy.get('[data-testid="highlight"]').should('contain.text', 'app');
    });

    cy.get('@searchInput').clear().type('apple');
    cy.get('[data-testid="suggestion-item"]').first().within(() => {
      cy.get('[data-testid="highlight"]').should('contain.text', 'apple');
    });
  });

  it('should handle special characters in search term', () => {
    cy.get('@searchInput').type('c++');
    cy.get('@suggestions').should('be.visible');

    cy.get('[data-testid="suggestion-item"]').first().within(() => {
      cy.get('[data-testid="highlight"]').should('exist');
      cy.get('[data-testid="highlight"]').invoke('text').then((text) => {
        expect(text).to.include('c');
      });
    });
  });

  it('should maintain highlight styling across different suggestion items', () => {
    cy.get('@searchInput').type('test');
    cy.get('@suggestions').should('be.visible');

    cy.get('[data-testid="suggestion-item"]').each(($item) => {
      cy.wrap($item).within(() => {
        cy.get('[data-testid="highlight"]').should('have.class', 'highlight-match');
        cy.get('[data-testid="highlight"]').should('have.css', 'font-weight', '700');
      });
    });
  });
});
